// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(address actor, address to, uint256 id) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));

        // No token is ever minted through the public surface, so every id is unminted.
        // Rule: moving an unminted token must always revert; ownerOf stays address(0).
        vm.prank(actor);
        bool ok;
        try c.transferFrom(actor, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: always reverts for unminted ids (never succeeds), so ownerOf(id) stays zero.
        // Mutant: succeeds (from != 0 and msg.sender == from), assigning ownerOf(id) = to.
        assertTrue(!ok && _revertsOnOwnerOf(id), "unminted token must be untransferable and stay unminted");
    }

    function _revertsOnOwnerOf(uint256 id) internal view returns (bool staysZero) {
        try c.ownerOf(id) returns (address owner) {
            staysZero = (owner == address(0));
        } catch {
            staysZero = true;
        }
    }
}
